def find_beautiful_sequence(k, q):
    if k > len(set(q)):
        return 'NO'

    used_chars = set()
    result = []
    current_string = ''

    for char in q:
        if char not in used_chars:
            if len(current_string) == k - 1:
                result.append(current_string + char)
                used_chars.update(current_string + char)
                current_string = ''
            else:
                current_string += char
        else:
            if current_string:
                result.append(current_string)
                used_chars.update(current_string)
                current_string = char
            else:
                return 'NO'

    if current_string:
        result.append(current_string)

    if len(result) == k and len(set([s[0] for s in result])) == k:
        return 'YES\n' + '\n'.join(result)
    else:
        return 'NO'

